using CustomCodeFramework.Core.Abstractions;using CustomCodeFramework.Cqrs.Commands;using CustomCodeFramework.Persistence.Abstractions;using Dhole.Content.Application.Abstractions.Auditing;using Dhole.Content.Application.Abstractions.Cache;using Dhole.Content.Application.Abstractions.Repositories;using Dhole.Content.Application.Auditing;namespace Dhole.Content.Application.ContentItems.PublishDueContent;public sealed class PublishDueContentCommandHandler(IContentItemRepository repo,IContentAuditService audit,IContentCacheService cache,IUnitOfWork uow,IDateTimeProvider clock):ICommandHandler<PublishDueContentCommand,int>{public async Task<int> HandleAsync(PublishDueContentCommand c,CancellationToken ct=default){var due=await repo.GetDueScheduledAsync(clock.UtcNow,c.BatchSize,ct);foreach(var x in due){var before=ContentAuditSnapshots.From(x);x.Publish(clock.UtcNow,null);await audit.PublishAsync(new ContentAuditEvent(ContentAuditEventTypes.ContentPublished,ContentAuditActions.Published,ContentAuditEntityTypes.ContentItem,x.Id,ActorUserName:"Dhole.Content.Worker",Before:before,After:ContentAuditSnapshots.From(x),Metadata:new{Automatic=true,Worker="ScheduledContentPublishingWorker"}),ct);}if(due.Count==0)return 0;await uow.SaveChangesAsync(ct);foreach(var x in due)await cache.RemoveContentAsync(x.SiteKey,x.Slug,ct);return due.Count;}}
